235	  DatanodeStorageInfo findStorageInfo(DatanodeDescriptor dn) {
236	    int len = getCapacity();
237	    DatanodeStorageInfo providedStorageInfo = null;
238	    for(int idx = 0; idx < len; idx++) {
239	      DatanodeStorageInfo cur = getStorageInfo(idx);
240	      if(cur != null) {
