244	            // do not return here as we have to check the other
245	            // DatanodeStorageInfos for this block which could be local
246	            providedStorageInfo = cur;
247	          }
248	        } else if (cur.getDatanodeDescriptor() == dn) {
249	          return cur;
250	        }
251	      }
252	    }
253	    return providedStorageInfo;
