258	   * @return index or -1 if not found.
259	   */
260	  int findStorageInfo(DatanodeStorageInfo storageInfo) {
261	    int len = getCapacity();
262	    for(int idx = 0; idx < len; idx++) {
263	      DatanodeStorageInfo cur = getStorageInfo(idx);
264	      if (cur == storageInfo) {
265	        return idx;
266	      }
