272	   * Insert this block into the head of the list of blocks
273	   * related to the specified DatanodeStorageInfo.
274	   * If the head is null then form a new list.
275	   * @return current block as the new head of the list.
276	   */
277	  BlockInfo listInsert(BlockInfo head, DatanodeStorageInfo storage) {
278	    int dnIndex = this.findStorageInfo(storage);
279	    assert dnIndex >= 0 : "Data node is not found: current";
280	    assert getPrevious(dnIndex) == null && getNext(dnIndex) == null :
281	        "Block is already in the list and cannot be inserted.";
282	    this.setPrevious(dnIndex, null);
283	    this.setNext(dnIndex, head);
284	    if (head != null) {
285	      head.setPrevious(head.findStorageInfo(storage), this);
286	    }
287	    return this;
288	  }
289	
290	  /**
291	   * Remove this block from the list of blocks
292	   * related to the specified DatanodeStorageInfo.
293	   * If this block is the head of the list then return the next block as
294	   * the new head.
295	   * @return the new head of the list or null if the list becomes
296	   * empy after deletion.
297	   */
298	  BlockInfo listRemove(BlockInfo head, DatanodeStorageInfo storage) {
299	    if (head == null) {
300	      return null;
301	    }
302	    int dnIndex = this.findStorageInfo(storage);
303	    if (dnIndex < 0) { // this block is not on the data-node list
304	      return head;
305	    }
306	
307	    BlockInfo next = this.getNext(dnIndex);
308	    BlockInfo prev = this.getPrevious(dnIndex);
309	    this.setNext(dnIndex, null);
310	    this.setPrevious(dnIndex, null);
311	    if (prev != null) {
312	      prev.setNext(prev.findStorageInfo(storage), next);
313	    }
314	    if (next != null) {
315	      next.setPrevious(next.findStorageInfo(storage), prev);
316	    }
317	    if (this == head) { // removing the head
318	      head = next;
319	    }
320	    return head;
321	  }
