328	   */
329	  public BlockInfo moveBlockToHead(BlockInfo head, DatanodeStorageInfo storage,
330	      int curIndex, int headIndex) {
331	    if (head == this) {
332	      return this;
333	    }
334	    BlockInfo next = this.setNext(curIndex, head);
335	    BlockInfo prev = this.setPrevious(curIndex, null);
336	
337	    head.setPrevious(headIndex, this);
338	    prev.setNext(prev.findStorageInfo(storage), next);
339	    if (next != null) {
340	      next.setPrevious(next.findStorageInfo(storage), prev);
341	    }
342	    return this;
343	  }
